html:
{% set items = doc.items %}
{% set payments = doc.payments %}

<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
<meta charset="UTF-8">
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', Tahoma, Arial, sans-serif; font-size: 13px; color: #1a1a1a; direction: rtl; }
  .page { max-width: 210mm; margin: 0 auto; padding: 20px; }
  .header { text-align: center; border-bottom: 3px solid #4338ca; padding-bottom: 15px; margin-bottom: 15px; }
  .company-name { font-size: 22px; font-weight: 900; color: #4338ca; letter-spacing: 1px; }
  .doc-title { font-size: 16px; font-weight: 700; color: #374151; margin-top: 4px; }
  .doc-number { font-size: 12px; color: #6b7280; margin-top: 2px; }
  .badges { display: flex; gap: 8px; justify-content: center; margin-top: 10px; }
  .badge { padding: 3px 12px; border-radius: 20px; font-size: 11px; font-weight: 700; }
  .badge-installment { background: #e0e7ff; color: #4338ca; border: 1px solid #a5b4fc; }
  .badge-date { background: #f0fdf4; color: #15803d; border: 1px solid #86efac; }

  .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 15px; }
  .info-box { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 10px 12px; }
  .info-box-title { font-size: 10px; font-weight: 700; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 5px; }
  .info-row { display: flex; justify-content: space-between; margin-bottom: 3px; }
  .info-label { color: #6b7280; font-size: 11px; }
  .info-value { font-weight: 600; font-size: 11px; color: #1a1a1a; }

  table { width: 100%; border-collapse: collapse; margin-bottom: 15px; }
  th { background: #4338ca; color: white; padding: 8px 10px; font-size: 11px; font-weight: 700; text-align: right; }
  td { padding: 7px 10px; font-size: 11px; border-bottom: 1px solid #f1f5f9; }
  tr:nth-child(even) td { background: #f8fafc; }
  .amount-col { text-align: left; font-weight: 600; }

  .totals-box { background: linear-gradient(135deg, #4338ca, #6366f1); border-radius: 10px; padding: 15px; color: white; margin-bottom: 15px; }
  .totals-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px; margin-bottom: 10px; }
  .total-item { text-align: center; }
  .total-label { font-size: 10px; opacity: 0.85; margin-bottom: 3px; }
  .total-value { font-size: 14px; font-weight: 800; }
  .grand-total-row { border-top: 1px solid rgba(255,255,255,0.3); padding-top: 10px; display: flex; justify-content: space-between; align-items: center; }
  .grand-total-label { font-size: 15px; font-weight: 700; }
  .grand-total-value { font-size: 22px; font-weight: 900; }

  .installment-section { border: 2px solid #4338ca; border-radius: 10px; overflow: hidden; margin-bottom: 15px; }
  .installment-header { background: #4338ca; color: white; padding: 10px 15px; font-size: 13px; font-weight: 700; display: flex; justify-content: space-between; }
  .installment-summary { display: grid; grid-template-columns: repeat(4, 1fr); gap: 0; border-bottom: 1px solid #e0e7ff; }
  .inst-sum-item { padding: 10px; text-align: center; border-left: 1px solid #e0e7ff; }
  .inst-sum-item:last-child { border-left: none; }
  .inst-sum-label { font-size: 10px; color: #6b7280; margin-bottom: 3px; }
  .inst-sum-value { font-size: 13px; font-weight: 800; color: #4338ca; }
  .schedule-table { width: 100%; }
  .schedule-table th { background: #ede9fe; color: #4338ca; padding: 7px 10px; font-size: 10px; }
  .schedule-table td { font-size: 10px; }
  .status-due { color: #d97706; font-weight: 600; }
  .status-paid { color: #15803d; font-weight: 600; }
  .status-late { color: #dc2626; font-weight: 600; }

  .signature-row { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-top: 20px; }
  .sig-box { border-top: 2px solid #4338ca; padding-top: 8px; text-align: center; }
  .sig-label { font-size: 11px; color: #6b7280; }
  .footer-note { text-align: center; font-size: 10px; color: #9ca3af; margin-top: 15px; border-top: 1px solid #e5e7eb; padding-top: 10px; }
  @media print { .page { padding: 5mm; } }
</style>
</head>
<body>
<div class="page">

  <!-- Header -->
  <div class="header">
    <div class="company-name">{{ doc.company }}</div>
    {% if doc.custom_is_installment_sale %}
    <div class="doc-title">فاتورة بيع بالتقسيط</div>
    {% else %}
    <div class="doc-title">فاتورة مبيعات</div>
    {% endif %}
    <div class="doc-number">رقم الفاتورة: {{ doc.name }}</div>
    <div class="badges">
      {% if doc.custom_is_installment_sale %}
      <span class="badge badge-installment">🏦 بيع بالتقسيط</span>
      {% endif %}
      <span class="badge badge-date">📅 {{ frappe.format(doc.posting_date, 'Date') }}</span>
    </div>
  </div>

  <!-- Customer + Invoice Info -->
  <div class="info-grid">
    <div class="info-box">
      <div class="info-box-title">بيانات العميل</div>
      <div class="info-row"><span class="info-label">الاسم</span><span class="info-value">{{ doc.customer_name }}</span></div>
      {% if doc.custom_customer_whatsapp %}
      <div class="info-row"><span class="info-label">واتساب</span><span class="info-value">{{ doc.custom_customer_whatsapp }}</span></div>
      {% endif %}
    </div>
    <div class="info-box">
      <div class="info-box-title">بيانات الفاتورة</div>
      <div class="info-row"><span class="info-label">التاريخ</span><span class="info-value">{{ frappe.format(doc.posting_date, 'Date') }}</span></div>
      <div class="info-row"><span class="info-label">طريقة الدفع</span><span class="info-value">{{ doc.custom_payment_mode or 'نقدي' }}</span></div>
      {% if doc.pos_profile %}
      <div class="info-row"><span class="info-label">نقطة البيع</span><span class="info-value">{{ doc.pos_profile }}</span></div>
      {% endif %}
    </div>
  </div>

  <!-- Items Table -->
  <table>
    <thead>
      <tr>
        <th>#</th>
        <th>الصنف</th>
        <th>الكمية</th>
        <th>السعر</th>
        <th>الإجمالي</th>
      </tr>
    </thead>
    <tbody>
      {% for item in items %}
      <tr>
        <td>{{ loop.index }}</td>
        <td>{{ item.item_name }}</td>
        <td>{{ item.qty }}</td>
        <td class="amount-col">{{ frappe.format(item.rate, {'fieldtype': 'Currency', 'currency': doc.currency}) }}</td>
        <td class="amount-col">{{ frappe.format(item.amount, {'fieldtype': 'Currency', 'currency': doc.currency}) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <!-- Totals -->
  <div class="totals-box">
    <div class="totals-grid">
      <div class="total-item">
        <div class="total-label">المجموع الفرعي</div>
        <div class="total-value">{{ frappe.format(doc.total, {'fieldtype': 'Currency', 'currency': doc.currency}) }}</div>
      </div>
      {% if doc.total_taxes_and_charges %}
      <div class="total-item">
        <div class="total-label">الضريبة</div>
        <div class="total-value">{{ frappe.format(doc.total_taxes_and_charges, {'fieldtype': 'Currency', 'currency': doc.currency}) }}</div>
      </div>
      {% endif %}
      {% if doc.discount_amount %}
      <div class="total-item">
        <div class="total-label">الخصم</div>
        <div class="total-value">-{{ frappe.format(doc.discount_amount, {'fieldtype': 'Currency', 'currency': doc.currency}) }}</div>
      </div>
      {% endif %}
    </div>
    <div class="grand-total-row">
      <span class="grand-total-label">الإجمالي الكلي</span>
      <span class="grand-total-value">{{ frappe.format(doc.grand_total, {'fieldtype': 'Currency', 'currency': doc.currency}) }}</span>
    </div>
  </div>

  <!-- Installment Section -->
  {% if doc.custom_is_installment_sale %}
  <div class="installment-section">
    <div class="installment-header">
      <span>📋 جدول الأقساط الشهرية</span>
      <span>{{ doc.custom_installment_months }} شهر</span>
    </div>
    <div class="installment-summary">
      <div class="inst-sum-item">
        <div class="inst-sum-label">الدفعة المقدمة</div>
        <div class="inst-sum-value">{{ frappe.format(doc.custom_installment_down_payment, {'fieldtype': 'Currency', 'currency': doc.currency}) }}</div>
      </div>
      <div class="inst-sum-item">
        <div class="inst-sum-label">نسبة الفائدة</div>
        <div class="inst-sum-value">{{ doc.custom_installment_interest_rate }}%</div>
      </div>
      <div class="inst-sum-item">
        <div class="inst-sum-label">إجمالي الفائدة</div>
        <div class="inst-sum-value">{{ frappe.format(doc.custom_installment_total_interest, {'fieldtype': 'Currency', 'currency': doc.currency}) }}</div>
      </div>
      <div class="inst-sum-item">
        <div class="inst-sum-label">القسط الشهري</div>
        <div class="inst-sum-value">{{ frappe.format(doc.custom_installment_monthly_amount, {'fieldtype': 'Currency', 'currency': doc.currency}) }}</div>
      </div>
    </div>
    {% if doc.custom_installment_schedule %}
    <table class="schedule-table">
      <thead>
        <tr>
          <th>رقم القسط</th>
          <th>تاريخ الاستحقاق</th>
          <th>قيمة القسط</th>
          <th>المدفوع</th>
          <th>المتبقي</th>
          <th>الحالة</th>
        </tr>
      </thead>
      <tbody>
        {% for row in doc.custom_installment_schedule %}
        <tr>
          <td>{{ row.installment_number }}</td>
          <td>{{ frappe.format(row.due_date, 'Date') }}</td>
          <td class="amount-col">{{ frappe.format(row.amount, {'fieldtype': 'Currency', 'currency': doc.currency}) }}</td>
          <td class="amount-col">{{ frappe.format(row.paid_amount, {'fieldtype': 'Currency', 'currency': doc.currency}) }}</td>
          <td class="amount-col">{{ frappe.format(row.remaining_amount, {'fieldtype': 'Currency', 'currency': doc.currency}) }}</td>
          <td class="{% if row.status == 'مدفوع' %}status-paid{% elif row.status == 'متأخر' %}status-late{% else %}status-due{% endif %}">{{ row.status }}</td>
        </tr>
        {% endfor %}
      </tbody>
    </table>
    {% endif %}
  </div>
  {% endif %}

  <!-- Signatures -->
  <div class="signature-row">
    <div class="sig-box"><div class="sig-label">توقيع البائع</div></div>
    <div class="sig-box"><div class="sig-label">توقيع العميل / المشتري</div></div>
  </div>

  <div class="footer-note">
    هذه الفاتورة صادرة من نظام {{ doc.company }} — شكراً لثقتكم
  </div>

</div>
</body>
</html>
